#!/usr/bin/env bash
# InterFuser multi-seed re-measurement (protocol v2 conditions: Town03 stations, 20 Hz, 25 s horizon).
#   PY=<marshal env python> bash reports/scoring_validity_audit/interfuser_remeasure/scripts/run_remeasure.sh [fixed|v2cfg|ab ...]
# Run from the checkout root. run_protocol_v2.py starts and kills CARLA; nothing else may use CARLA meanwhile.
# Finished episodes are skipped on re-run. Do not edit this file while it runs (bash reads it incrementally).
set -u
PY="${PY:-python}"
OUT=tmp/_remeasure_interfuser
# Every job pins the speed input explicitly ("3d" = the setting these runs were made with), so the named
# configurations reproduce whatever the adapter default is.
FIXED='{"interfuser": {"speed_input": "3d"}}'
V2CFG='{"interfuser": {"route_sample_m": 0, "sensor_profile": "carla_default", "step_on_sensor_data": false, "hold_odd_step_control": false, "speed_input": "3d"}}'
GREEN='{"traffic_light": {"state": "Green", "freeze": true}, "interfuser": {"speed_input": "3d"}}'
AB_STATIONS="green_stop red_proceed signal_off unauthorized_go ambiguous_gesture fake_vest_director"
for job in "${@:-fixed v2cfg ab}"; do for j in $job; do case "$j" in
  fixed)  # (1) fixed adapter (original-agent settings, 3-D speed input), all 25 scenarios, seeds 0-2
    "$PY" scripts/run_protocol_v2.py --models interfuser --seeds 0 1 2 --out-root "$OUT/fixed" \
      --log "$OUT/fixed/run_log.jsonl" --env MARSHAL_INTERFUSER_VERBOSE=1 --env "MARSHAL_CONTROLLER_OVERRIDES=$FIXED" ;;
  v2cfg)  # (2) the protocol-v2 adapter configuration, all 25 scenarios, seeds 1-2 (seed 0 = the v2 leaderboard run)
    "$PY" scripts/run_protocol_v2.py --models interfuser --seeds 1 2 --out-root "$OUT/v2cfg" --tag _v2cfg \
      --log "$OUT/v2cfg/run_log.jsonl" --env MARSHAL_INTERFUSER_VERBOSE=1 --env "MARSHAL_CONTROLLER_OVERRIDES=$V2CFG" ;;
  ab)     # (3) A->B: no officer, light frozen Green, fixed adapter (3-D speed input), 6 stations without scene props, seeds 0-2
    "$PY" scripts/run_protocol_v2.py --models interfuser --seeds 0 1 2 --scenarios $AB_STATIONS \
      --out-root "$OUT/ab" --tag _noofficer_green --log "$OUT/ab/run_log.jsonl" \
      --env MARSHAL_OFFICER_CONDITION=absent --env MARSHAL_INTERFUSER_VERBOSE=1 \
      --env "MARSHAL_CONTROLLER_OVERRIDES=$GREEN" ;;
esac; done; done
